// Steam + Millennium (live): liest Steam-Daten ueber pc.steam() im 1-s-Takt.
// Nur Lesen: die Daten kommen vom Agenten, nicht aus Dateien.
var letzt = null;          // letzter gemeldeter Status (Aenderungserkennung)
var einmalig = {};         // einmalige Hinweise (kein Dauer-Spam)

function zahl(wert) {
  var n = Number(wert);
  return isFinite(n) ? n : 0;
}

// Fortschritt immer mit genau einer Nachkommastelle.
function prozentText(wert) {
  return zahl(wert).toFixed(1);
}

// Name eines Downloads, mit Ersatzname falls das Feld fehlt.
function nameVon(eintrag, nummer) {
  var name = eintrag && eintrag.name ? String(eintrag.name) : "";
  if (name === "") {
    name = "App " + String(eintrag && eintrag.app_id ? eintrag.app_id : nummer);
  }
  return name;
}

// "4.2 MB/s" - der Agent liefert Bytes pro Sekunde (speed_bps).
// Netzwerk-Tempo wird dezimal gerechnet (wie im Steam-Client), nicht binaer.
function tempoText(bps) {
  var wert = zahl(bps);
  if (wert <= 0) {
    return "";
  }
  if (wert >= 1000000000) {
    return (wert / 1000000000).toFixed(1) + " GB/s";
  }
  if (wert >= 1000000) {
    return (wert / 1000000).toFixed(1) + " MB/s";
  }
  if (wert >= 1000) {
    return Math.round(wert / 1000) + " KB/s";
  }
  return Math.round(wert) + " B/s";
}

// "noch 12 Min." - Restzeit aus eta_seconds.
function restText(sekunden) {
  var s = zahl(sekunden);
  if (s <= 0) {
    return "";
  }
  if (s < 60) {
    return s + " Sek.";
  }
  if (s < 3600) {
    return Math.round(s / 60) + " Min.";
  }
  return Math.round(s / 3600) + " Std.";
}

function activate() {
  pc.log("Steam + Millennium (live) aktiv (Takt 1 s)");
  einmalig = {};
}

function tick() {
  var steam = pc.steam();
  if (!steam) {
    pc.log("Steam: keine Daten vom Agenten");
    return;
  }

  // Einmalig beim Start: Steam-Erkennung melden
  if (!einmalig.steamErkannt) {
    var pfad = steam.steam_path || "unbekannt";
    var mill = steam.millennium ? "mit Millennium" : "ohne Millennium";
    var laeuft = steam.running ? "laeuft" : "gestoppt";
    pc.log("Steam erkannt: " + pfad + " (" + mill + ", " + laeuft + ")");
    einmalig.steamErkannt = true;
  }

  // Download-Status aendern?
  var dl = steam.downloading;
  if (dl !== einmalig.warDownloading) {
    pc.log("Download-Status: " + (dl ? "laeuft" : "kein Download"));
    einmalig.warDownloading = dl;
  }

  if (!dl) {
    pc.setStatus("Kein Download");
    return;
  }

  // Primärer Download (wie im Agent: der am weitesten fortgeschrittene)
  var downloads = steam.downloads || [];
  if (downloads.length === 0) {
    pc.setStatus("Download: keine Details");
    return;
  }

  // Sortierung nach Fortschritt (absteigend)
  downloads.sort(function(a, b) { return zahl(b.percent) - zahl(a.percent); });
  var prim = downloads[0];

  var name = nameVon(prim, 0);
  var prozent = prozentText(prim.percent);
  var tempo = tempoText(prim.speed_bps);
  var rest = restText(prim.eta_seconds);

  // Staging-Info falls Download-Bytes 0 aber Staging > 0
  var stagingInfo = "";
  if (zahl(prim.bytes_downloaded) === 0 && zahl(prim.bytes_staged) > 0) {
    var stProzent = prozentText(prim.percent_staged);
    stagingInfo = " (Staging: " + stProzent + "%)";
  }

  var zeile = name + ": " + prozent + "%" + stagingInfo;
  if (tempo !== "") zeile += " @ " + tempo;
  if (rest !== "") zeile += " - " + rest;

  // Nur loggen wenn sich was geaendert hat
  if (zeile !== letzt) {
    pc.log(zeile);
    letzt = zeile;
  }
  pc.setStatus(zeile);

  // Einmalig: andere Downloads auflisten
  if (!einmalig.alleDownloads && downloads.length > 1) {
    var andere = downloads.slice(1).map(function(d) {
      return nameVon(d, 0) + " (" + prozentText(d.percent) + "%)";
    }).join(", ");
    pc.log("Weitere Downloads: " + andere);
    einmalig.alleDownloads = true;
  }
}

function stop() {
  pc.log("Steam + Millennium (live) beendet");
}
